script:
// Rede Wi-Fi (OpenWrt) — SSIDs, roaming, mesh e canais de vários roteadores.
//
// O roteador é a fonte da verdade. Nada fica guardado no NetMonitor: cada
// ação lê o `/etc/config/wireless` do roteador, calcula só o que muda para
// atender o pedido e aplica com cópia, conferência e volta atrás. O que
// alguém mudar à mão aparece na próxima leitura.
//
// As senhas do Wi-Fi não saem do roteador: a leitura já vem com elas
// mascaradas, e quando uma senha existente precisa ir para outra seção ela é
// copiada lá dentro (`$(uci -q get …)`). Só a senha nova digitada pelo
// operador passa pela central — e ela é parâmetro secreto, mascarado.

// ---------------------------------------------------------------- leitura

fn unquote(raw) {
    let v = trimmed(raw);
    if v.len() >= 2 && v.starts_with("'") && v.ends_with("'") {
        v = v.sub_string(1, v.len() - 2);
    }
    v.replace("'\\''", "'");
    v
}

// `uci show wireless` com as senhas trocadas por ******** no próprio roteador.
fn read_command() {
    "uci show wireless | sed -E " + shell_quote("s/^(wireless\\.[^.=]+\\.(key|sae_password|password))=.*/\\1='********'/")
}

// → #{ seção: #{ kind, options } }.
fn read_wireless(device) {
    let sections = #{};
    for line in lines(device.run(read_command())) {
        let sec = regex_groups(line, "^wireless\\.([^.=]+)=([A-Za-z0-9_-]+)$");
        if sec != () {
            sections[sec[0]] = #{ kind: sec[1], options: #{} };
            continue;
        }
        let opt = regex_groups(line, "^wireless\\.([^.=]+)\\.([^=]+)=(.*)$");
        if opt != () && sections.contains(opt[0]) {
            sections[opt[0]].options[opt[1]] = unquote(opt[2]);
        }
    }
    sections
}

fn band_of(options) {
    if options.contains("band") { return options.band; }
    let hw = options.hwmode ?? "";
    if hw == "11a" { return "5g"; }
    let ch = options.channel ?? "auto";
    if ch != "auto" && parse_int(ch) > 14 { return "5g"; }
    "2g"
}

fn band_label(band) {
    if band == "2g" { return "2,4 GHz"; }
    if band == "5g" { return "5 GHz"; }
    if band == "6g" { return "6 GHz"; }
    band
}

// Banda → o primeiro rádio dela.
fn radios_by_band(sections) {
    let found = #{};
    for name in sections.keys() {
        let section = sections[name];
        if section.kind == "wifi-device" {
            let band = band_of(section.options);
            if !found.contains(band) { found[band] = name; }
        }
    }
    found
}

fn section_band(sections, section) {
    let radio = section.options.device ?? "";
    if sections.contains(radio) { band_of(sections[radio].options) } else { "?" }
}

fn is_ap(section) {
    section.kind == "wifi-iface" && (section.options.mode ?? "ap") == "ap"
}

// As seções de uma rede: #{ banda: seção } (a primeira de cada banda).
fn ap_sections(sections, ssid) {
    let found = #{};
    for name in sections.keys() {
        let section = sections[name];
        if !is_ap(section) || (section.options.ssid ?? "") != ssid { continue; }
        let band = section_band(sections, section);
        if !found.contains(band) { found[band] = name; }
    }
    found
}

fn runtime_status(device) {
    let r = device.ssh("ubus call network.wireless status");
    if r.exit != 0 || trimmed(r.stdout) == "" { return #{}; }
    json_parse(r.stdout)
}

fn ifname_of(rt, section) {
    for radio in rt.keys() {
        for iface in rt[radio].interfaces ?? [] {
            if iface.section == section { return iface.ifname ?? (); }
        }
    }
    ()
}

fn clients(device, ifname) {
    if ifname == () { return 0; }
    let out = device.ssh("iwinfo " + shell_quote(ifname) + " assoclist");
    let total = 0;
    for line in lines(out.stdout) {
        if regex_match(line, "^[0-9A-Fa-f]{2}(:[0-9A-Fa-f]{2}){5}") { total += 1; }
    }
    total
}

// ---------------------------------------------------------------- plano

fn set_command(section, option, value) {
    "uci set wireless." + section + "." + option + "=" + shell_quote(value)
}

fn new_plan() {
    #{ commands: [], changes: [] }
}

// Opções que este plugin escreve numa rede; as demais da seção ficam como o
// roteador tem.
fn managed_keys() {
    ["hidden", "isolate", "ieee80211w", "ieee80211r", "mobility_domain", "ft_over_ds",
     "ft_psk_generate_local", "ieee80211k", "rrm_neighbor_report", "rrm_beacon_report",
     "bss_transition"]
}

fn iface_options(n, radio) {
    let o = #{ device: radio, mode: "ap", network: n.network, ssid: n.ssid, encryption: n.encryption,
               disabled: if n.enabled { "0" } else { "1" } };
    if n.hidden { o.hidden = "1"; }
    if n.isolate { o.isolate = "1"; }
    if n.encryption == "sae" { o.ieee80211w = "2"; }
    if n.encryption == "sae-mixed" { o.ieee80211w = "1"; }
    if n.roaming && n.encryption != "none" {
        o.ieee80211r = "1";
        o.mobility_domain = hash_hex(n.ssid, 4);
        o.ft_over_ds = "0";
        o.ft_psk_generate_local = "1";
        o.ieee80211k = "1";
        o.rrm_neighbor_report = "1";
        o.rrm_beacon_report = "1";
        o.bss_transition = "1";
    }
    o
}

// Valor de uma opção como o UCI entende: ausente vale o padrão.
fn have(current, k) {
    let v = current[k];
    if v == () && k == "disabled" { return "0"; }
    if v == () && k == "mode" { return "ap"; }
    v
}

// Diferença das opções (sem a senha): comandos e os nomes do que mudou.
fn option_commands(name, current, want, managed) {
    let commands = [];
    let diff = [];
    for k in want.keys() {
        if have(current, k) != want[k] {
            commands.push(set_command(name, k, want[k]));
            diff.push(k);
        }
    }
    for k in managed {
        if !want.contains(k) && current.contains(k) {
            commands.push("uci delete wireless." + name + "." + k);
            diff.push(k);
        }
    }
    #{ commands: commands, diff: diff }
}

// A senha de uma seção: a nova, a que o roteador já tem (fica onde está ou é
// copiada de outra seção da mesma rede, sem sair do roteador) ou nenhuma.
fn key_commands(name, current, encryption, key, sibling) {
    let has = (current.key ?? "") != "";
    if encryption == "none" {
        if has { return ["uci delete wireless." + name + ".key"]; }
        return [];
    }
    if key != "" { return [set_command(name, "key", key)]; }
    if has { return []; }
    if sibling == () { throw "Informe a senha da rede (8 a 63 caracteres)."; }
    ["uci set wireless." + name + ".key=\"$(uci -q get wireless." + sibling + ".key)\""]
}

fn check_key(key, label) {
    if key != "" && (key.len() < 8 || key.len() > 63) {
        throw "A senha " + label + " precisa ter de 8 a 63 caracteres.";
    }
}

// Garante a rede `ssid` com estas opções nas bandas marcadas deste roteador.
// `original_ssid` renomeia a rede existente.
fn plan_network(sections, n) {
    let ssid = n.ssid;
    let target = if (n.original_ssid ?? "") != "" { n.original_ssid } else { ssid };
    if n.band_6g && n.encryption != "sae" { throw "Em 6 GHz a rede precisa de WPA3 (sae)."; }
    if !n.band_2g && !n.band_5g && !n.band_6g {
        throw "Marque ao menos uma banda. Para tirar a rede do roteador, use Remover rede.";
    }
    if target != ssid && ap_sections(sections, ssid).len() > 0 {
        throw "Já existe a rede " + ssid + " neste roteador.";
    }
    let key = n.key ?? "";
    check_key(key, "da rede " + ssid);
    let radios = radios_by_band(sections);
    let current = ap_sections(sections, target);
    let sibling = ();
    for band in current.keys() {
        if (sections[current[band]].options.key ?? "") != "" { sibling = current[band]; }
    }
    let p = new_plan();
    for band in ["2g", "5g", "6g"] {
        let wanted = n["band_" + band];
        let name = current[band];
        if !wanted {
            if name != () {
                p.commands.push("uci delete wireless." + name);
                p.changes.push(#{ change: "remover", "_section": name, ssid: target, detail: band_label(band) });
            }
            continue;
        }
        if !radios.contains(band) {
            p.changes.push(#{ change: "ignorar", "_section": "", ssid: ssid, detail: "o roteador não tem rádio de " + band_label(band) });
            continue;
        }
        let radio = radios[band];
        let want = iface_options(n, radio);
        if name == () {
            let fresh = "nm_" + hash_hex(ssid, 8) + "_" + band;
            while sections.contains(fresh) { fresh += "x"; }
            p.commands.push("uci set wireless." + fresh + "=wifi-iface");
            for k in want.keys() { p.commands.push(set_command(fresh, k, want[k])); }
            p.commands += key_commands(fresh, #{}, n.encryption, key, sibling);
            p.changes.push(#{ change: "criar", "_section": fresh, ssid: ssid, detail: band_label(band) });
        } else {
            let options = sections[name].options;
            let q = option_commands(name, options, want, managed_keys());
            let keys = key_commands(name, options, n.encryption, key, sibling);
            p.commands += q.commands;
            p.commands += keys;
            if keys.len() > 0 { q.diff.push("senha"); }
            if q.diff.len() > 0 {
                p.changes.push(#{ change: "alterar", "_section": name, ssid: ssid, detail: friendly(q.diff) });
            }
        }
        if n.enabled && (sections[radio].options.disabled ?? "0") == "1" {
            p.commands.push(set_command(radio, "disabled", "0"));
            p.changes.push(#{ change: "rádio", "_section": radio, ssid: band_label(band), detail: "ligar o rádio (a rede precisa dele no ar)" });
        }
    }
    p
}

fn plan_remove(sections, n) {
    let p = new_plan();
    for name in sections.keys() {
        let section = sections[name];
        if is_ap(section) && (section.options.ssid ?? "") == n.ssid {
            p.commands.push("uci delete wireless." + name);
            p.changes.push(#{ change: "remover", "_section": name, ssid: n.ssid, detail: band_label(section_band(sections, section)) });
        }
    }
    p
}

fn check_channel(band, ch) {
    if ch == "auto" { return; }
    let c = parse_int(ch);
    let ok = if band == "2g" { c >= 1 && c <= 14 } else if band == "5g" { c >= 32 && c <= 177 } else { c >= 1 && c <= 233 };
    if !ok { throw "O canal " + ch + " não existe em " + band_label(band) + "."; }
}

fn check_htmode(band, ht) {
    if band == "2g" && (ht.contains("80") || ht.contains("160") || ht.contains("320")) {
        throw "A largura " + ht + " não existe em 2,4 GHz (use 20 ou 40).";
    }
    if band == "6g" && !ht.starts_with("HE") && !ht.starts_with("EHT") {
        throw "Em 6 GHz a largura precisa ser HE ou EHT.";
    }
}

// Canal, largura, potência, ligado/desligado de cada rádio e o país. Campo
// vazio = manter o que o roteador tem.
fn plan_radio(sections, n) {
    let radios = radios_by_band(sections);
    let country = n.country ?? "";
    let p = new_plan();
    for band in ["2g", "5g", "6g"] {
        let prefix = "radio_" + band + "_";
        let want = #{};
        let ch = n[prefix + "channel"] ?? "";
        if ch != "" { check_channel(band, ch); want.channel = ch; }
        let ht = n[prefix + "htmode"] ?? "";
        if ht != "" { check_htmode(band, ht); want.htmode = ht; }
        let tx = n[prefix + "txpower"];
        if tx != () { want.txpower = tx.to_string(); }
        let state = n[prefix + "state"] ?? "";
        if state == "ligado" { want.disabled = "0"; }
        if state == "desligado" { want.disabled = "1"; }
        if !radios.contains(band) {
            if want.len() > 0 {
                p.changes.push(#{ change: "ignorar", "_section": "", ssid: band_label(band), detail: "o roteador não tem rádio desta banda" });
            }
            continue;
        }
        if country != "" { want.country = country; }
        let radio = radios[band];
        let current = sections[radio].options;
        let diff = [];
        for k in want.keys() {
            if (current[k] ?? ()) != want[k] {
                p.commands.push(set_command(radio, k, want[k]));
                diff.push(radio_change(k, want[k]));
            }
        }
        if diff.len() > 0 {
            p.changes.push(#{ change: "rádio", "_section": radio, ssid: band_label(band), detail: join_with(diff, ", ") });
        }
    }
    p
}

// Mesh 802.11s numa banda (seção `nm_mesh_<banda>`); desligar tira as seções.
fn plan_mesh(sections, n) {
    let radios = radios_by_band(sections);
    let key = n.key ?? "";
    check_key(key, "do mesh");
    let p = new_plan();
    for band in ["2g", "5g"] {
        let name = "nm_mesh_" + band;
        let exists = sections.contains(name);
        if !n.enabled || n.band != band {
            if exists {
                p.commands.push("uci delete wireless." + name);
                p.changes.push(#{ change: "remover", "_section": name, ssid: "Mesh", detail: band_label(band) });
            }
            continue;
        }
        if !radios.contains(band) { throw "O roteador não tem rádio de " + band_label(band) + " para o mesh."; }
        if n.mesh_id == "" { throw "Informe o identificador do mesh."; }
        let want = #{ device: radios[band], mode: "mesh", mesh_id: n.mesh_id, encryption: "sae",
                      network: n.network, mesh_fwding: "1", mesh_rssi_threshold: "0", disabled: "0" };
        let current = if exists { sections[name].options } else { #{} };
        if !exists {
            p.commands.push("uci set wireless." + name + "=wifi-iface");
            for k in want.keys() { p.commands.push(set_command(name, k, want[k])); }
        }
        let q = if exists { option_commands(name, current, want, []) } else { #{ commands: [], diff: [] } };
        let keys = key_commands(name, current, "sae", key, ());
        p.commands += q.commands;
        p.commands += keys;
        if !exists {
            p.changes.push(#{ change: "criar", "_section": name, ssid: "Mesh " + n.mesh_id, detail: band_label(band) });
        } else {
            if keys.len() > 0 { q.diff.push("senha"); }
            if q.diff.len() > 0 {
                p.changes.push(#{ change: "alterar", "_section": name, ssid: "Mesh " + n.mesh_id, detail: friendly(q.diff) });
            }
        }
    }
    p
}

fn plan_of(op, sections, params) {
    if op == "network" { return plan_network(sections, params); }
    if op == "remove" { return plan_remove(sections, params); }
    if op == "radio" { return plan_radio(sections, params); }
    if op == "mesh" { return plan_mesh(sections, params); }
    throw "operação desconhecida: " + op;
}

// O que mudou, em palavras de gente (e não opções do UCI).
fn friendly(keys) {
    let words = [];
    for k in keys {
        let w = if k == "ssid" { "nome" }
            else if k == "encryption" || k == "ieee80211w" { "segurança" }
            else if k == "senha" { "senha" }
            else if k == "hidden" { "rede oculta" }
            else if k == "isolate" { "isolamento de clientes" }
            else if k == "network" { "interface" }
            else if k == "disabled" { "ativa/desativada" }
            else if k == "device" { "rádio" }
            else if k == "mesh_id" { "identificador do mesh" }
            else if ["ieee80211r", "mobility_domain", "ft_over_ds", "ft_psk_generate_local", "ieee80211k",
                     "rrm_neighbor_report", "rrm_beacon_report", "bss_transition"].contains(k) { "roaming" }
            else { k };
        if !words.contains(w) { words.push(w); }
    }
    join_with(words, ", ")
}

fn radio_change(k, v) {
    if k == "channel" { return if v == "auto" { "canal automático" } else { "canal " + v }; }
    if k == "htmode" { return "largura " + width_label(v); }
    if k == "txpower" { return "potência " + v + " dBm"; }
    if k == "disabled" { return if v == "1" { "desligar o rádio" } else { "ligar o rádio" }; }
    if k == "country" { return "país " + v; }
    k + " " + v
}

fn width_label(ht) {
    let mhz = regex_capture(ht, "([0-9]+)$");
    if mhz == () { "padrão" } else { mhz + " MHz" }
}

fn security_label(encryption) {
    if encryption == "sae-mixed" { return "WPA2/WPA3"; }
    if encryption == "psk2" || encryption == "psk2+ccmp" || encryption == "psk-mixed" { return "WPA2"; }
    if encryption == "sae" { return "WPA3"; }
    if encryption == "none" { return "Aberta"; }
    encryption
}

fn summary_of(changes) {
    let s = #{ create: 0, update: 0, remove: 0, radios: 0 };
    for c in changes {
        if c.change == "criar" { s.create += 1; }
        if c.change == "alterar" { s.update += 1; }
        if c.change == "remover" { s.remove += 1; }
        if c.change == "rádio" { s.radios += 1; }
    }
    s
}

fn summary_text(changes) {
    if changes.len() == 0 { return "Nada a mudar neste equipamento."; }
    changes.len().to_string() + " mudança(s) neste equipamento."
}

fn preview(device, op, params) {
    let p = plan_of(op, read_wireless(device), params);
    #{ summary: summary_text(p.changes), changes: p.changes, commands: p.commands, "_counts": summary_of(p.changes) }
}

// Aplica com cópia do arquivo, confere o resultado e restaura se o roteador
// não ficou como pedido ou se um rádio que estava no ar caiu.
fn execute(device, op, params) {
    let p = plan_of(op, read_wireless(device), params);
    if p.commands.len() == 0 {
        return "Nada a alterar: o roteador já está assim.";
    }
    let before = runtime_status(device);
    device.run("cp /etc/config/wireless /tmp/netmonitor-wireless.bak");
    let staged = device.ssh(join_with(p.commands, " && "));
    if staged.exit != 0 {
        device.ssh("uci revert wireless");
        throw "O roteador recusou a configuração (nada foi gravado):\n" + staged.stdout + staged.stderr;
    }
    device.run("uci commit wireless");
    let reload = device.ssh("wifi reload");
    let after = device.ssh("sleep 5; ubus call network.wireless status");

    // Conferência: o mesmo pedido, sobre o que ficou gravado, não muda nada
    // (a rede já tem o nome novo; a senha ficou onde foi posta).
    let settled = params;
    settled.original_ssid = "";
    settled.key = "";
    let now = read_wireless(device);
    let problems = [];
    if plan_of(op, now, settled).commands.len() > 0 {
        problems.push("a configuração gravada não confere com a pedida");
    }
    if after.exit == 0 && trimmed(after.stdout) != "" {
        let live = json_parse(after.stdout);
        for radio in before.keys() {
            let was_up = before[radio].up ?? false;
            let off = now.contains(radio) && (now[radio].options.disabled ?? "0") == "1";
            let is_up = if live.contains(radio) { live[radio].up ?? false } else { false };
            if was_up && !off && !is_up { problems.push("o rádio " + radio + " estava no ar e não voltou"); }
        }
    }
    if problems.len() > 0 {
        device.ssh("cp /tmp/netmonitor-wireless.bak /etc/config/wireless && wifi reload");
        throw "A aplicação falhou (" + join_with(problems, "; ") + "). A configuração anterior foi restaurada.\n" + reload.stdout + reload.stderr;
    }
    let text = "Configuração aplicada: " + p.changes.len() + " alteração(ões).\n";
    for c in p.changes {
        let verb = c.change;
        text += "- " + verb.sub_string(0, 1).to_upper() + verb.sub_string(1) + " " + c.ssid;
        if c.detail != "" { text += ": " + c.detail; }
        text += "\n";
    }
    text
}

// ---------------------------------------------------------- pacotes (DRY)

fn installed_names(device) {
    let names = [];
    for row in device.use_plugin("openwrt-packages", "list_packages", #{}) { names.push(row.name); }
    names
}

fn wpad_of(names) {
    let found = "nenhum";
    for name in names { if name.starts_with("wpad") { found = name; } }
    found
}

fn installed_wpad(device) { wpad_of(installed_names(device)) }

fn wpad_is_full(name) {
    name != "nenhum" && !name.contains("basic") && !name.contains("mini")
}

// ---------------------------------------------------------------- ações

fn detect(device, params) {
    let base = device.use_plugin("openwrt-packages", "detect", #{});
    let radios = radios_by_band(read_wireless(device));
    let bands = [];
    for band in radios.keys() { bands.push(band_label(band)); }
    let wpad = installed_wpad(device);
    #{
        firmware: base.firmware,
        model: base.model,
        package_manager: base.package_manager,
        radios: join_with(bands, ", "),
        wpad: wpad,
        roaming_ready: wpad_is_full(wpad),
        mesh_ready: wpad_is_full(wpad) || wpad.contains("mesh")
    }
}

// As redes como o roteador tem agora, agrupadas por SSID.
fn networks_of(device, sections, rt) {
    let groups = #{};
    for name in sections.keys() {
        let section = sections[name];
        if !is_ap(section) { continue; }
        let o = section.options;
        let ssid = o.ssid ?? "";
        if ssid == "" { continue; }
        if !groups.contains(ssid) {
            groups[ssid] = #{
                ssid: ssid, band_2g: false, band_5g: false, band_6g: false,
                encryption: o.encryption ?? "none", network: o.network ?? "lan",
                roaming: (o.ieee80211r ?? "0") == "1", hidden: (o.hidden ?? "0") == "1",
                isolate: (o.isolate ?? "0") == "1", enabled: false, clients: 0, sections: []
            };
        }
        let g = groups[ssid];
        let band = section_band(sections, section);
        if band == "2g" || band == "5g" || band == "6g" { g["band_" + band] = true; }
        if (o.disabled ?? "0") != "1" {
            g.enabled = true;
            g.clients += clients(device, ifname_of(rt, name));
        }
        g.sections.push(name);
        groups[ssid] = g;
    }
    let rows = [];
    for ssid in groups.keys() {
        let g = groups[ssid];
        let bands = [];
        for band in ["2g", "5g", "6g"] { if g["band_" + band] { bands.push(band_label(band)); } }
        g.bands = join_with(bands, ", ");
        g.state = if g.enabled { "ativa" } else { "desativada" };
        g.security = security_label(g.encryption);
        g.sections = join_with(g.sections, ", ");
        rows.push(g);
    }
    rows
}

fn status(device, params) {
    let sections = read_wireless(device);
    let rt = runtime_status(device);
    let radios = radios_by_band(sections);
    let radio_rows = [];
    let any_up = false;
    let all_off = true;
    for band in radios.keys() {
        let name = radios[band];
        let o = sections[name].options;
        let up = if rt.contains(name) { rt[name].up ?? false } else { false };
        let disabled = (o.disabled ?? "0") == "1";
        if up { any_up = true; }
        if !disabled { all_off = false; }
        radio_rows.push(#{
            radio: name, band: band_label(band), channel: o.channel ?? "auto", htmode: o.htmode ?? "",
            txpower: o.txpower ?? "", country: o.country ?? "", disabled: disabled, up: up
        });
    }
    let mesh = [];
    for name in sections.keys() {
        let section = sections[name];
        if section.kind == "wifi-iface" && (section.options.mode ?? "") == "mesh" {
            mesh.push(#{
                section: name, mesh_id: section.options.mesh_id ?? "", band: band_label(section_band(sections, section)),
                state: if (section.options.disabled ?? "0") == "1" { "desativada" } else { "ativa" }
            });
        }
    }
    let state = if radios.len() == 0 { "sem_radio" } else if any_up { "no_ar" } else if all_off { "desligado" } else { "fora_do_ar" };
    let networks = networks_of(device, sections, rt);
    // O cartão do roteador na tela: cada rádio e os números que importam.
    let card = [];
    for row in radio_rows {
        card.push(#{ label: row.band, value: if row.disabled { "desligado" } else { (if row.channel == "auto" { "canal automático" } else { "canal " + row.channel }) + " · " + width_label(row.htmode) } });
    }
    let total = 0;
    for n in networks { total += n.clients; }
    card.push(#{ label: "Redes", value: networks.len().to_string() });
    card.push(#{ label: "Clientes", value: total.to_string() });
    #{
        state: state, networks: networks, radios: radio_rows, mesh: mesh,
        "_card": card,
        // Os valores atuais no formato dos formulários de "Rádios e canais" e
        // "Mesh" — a tela mostra e preenche; chave com `_` não vai ao relatório.
        "_current": #{ radios: radio_form(sections, radios), mesh: mesh_form(sections) }
    }
}

fn radio_form(sections, radios) {
    let form = #{ country: "" };
    for band in radios.keys() {
        let o = sections[radios[band]].options;
        let prefix = "radio_" + band + "_";
        form[prefix + "channel"] = o.channel ?? "";
        form[prefix + "htmode"] = o.htmode ?? "";
        let tx = o.txpower ?? "";
        if tx != "" { form[prefix + "txpower"] = parse_int(tx); }
        form[prefix + "state"] = if (o.disabled ?? "0") == "1" { "desligado" } else { "ligado" };
        if form.country == "" { form.country = o.country ?? ""; }
    }
    form
}

fn mesh_form(sections) {
    for band in ["5g", "2g"] {
        let name = "nm_mesh_" + band;
        if sections.contains(name) {
            let o = sections[name].options;
            return #{ enabled: (o.disabled ?? "0") != "1", mesh_id: o.mesh_id ?? "", band: band, network: o.network ?? "lan" };
        }
    }
    #{ enabled: false }
}

