fn parse_scan(text) {
    let cells = [];
    let current = ();
    for line in lines(text) {
        if line.starts_with("Cell ") {
            if current != () { cells.push(current); }
            current = #{ ssid: "", channel: 0, signal: -100 };
            continue;
        }
        if current == () { continue; }
        let essid = regex_capture(line, "ESSID: \"(.*)\"");
        if essid != () { current.ssid = essid; }
        let channel = regex_capture(line, "Channel: (\\d+)");
        if channel != () { current.channel = parse_int(channel); }
        let signal = regex_capture(line, "Signal: (-?\\d+) dBm");
        if signal != () { current.signal = parse_int(signal); }
    }
    if current != () { cells.push(current); }
    cells
}

// Os canais que o rádio pode usar no país configurado (`iwinfo freqlist`).
// Restritos (radar/DFS, "no IR") e desligados ficam de fora: o plano nunca
// sugere um canal que o roteador não pode transmitir sozinho.
fn parse_freqlist(text) {
    let channels = [];
    for line in lines(text) {
        let ch = regex_capture(line, "Channel (\\d+)");
        if ch == () { continue; }
        let lower = line.to_lower();
        if lower.contains("restricted") || lower.contains("no ir") || lower.contains("disabled") { continue; }
        channels.push(parse_int(ch));
    }
    channels
}

fn scan(device, params) {
    let sections = read_wireless(device);
    let radios = radios_by_band(sections);
    let rt = runtime_status(device);
    let own = [];
    for name in sections.keys() {
        let section = sections[name];
        let ssid = section.options.ssid ?? "";
        if is_ap(section) && ssid != "" && !own.contains(ssid) { own.push(ssid); }
    }
    let targets = [];
    for band in radios.keys() {
        let radio = radios[band];
        if !rt.contains(radio) { continue; }
        let ifaces = rt[radio].interfaces ?? [];
        if ifaces.len() == 0 { continue; }
        let ifname = ifaces[0].ifname ?? ();
        if ifname == () { continue; }
        targets.push(#{ radio: radio, band: band, ifname: ifname });
    }
    let rows = [];
    if targets.len() > 0 {
        // A varredura leva segundos por rádio: todos ao mesmo tempo, e cada
        // linha da saída marcada com o índice do rádio para separar depois
        // (`f<i>|` é a lista de canais permitidos do mesmo rádio).
        let parts = [];
        for i in 0..targets.len() {
            let ifname = shell_quote(targets[i].ifname);
            parts.push("iwinfo " + ifname + " scan 2>&1 | sed " + shell_quote("s/^/" + i + "|/") + " &");
            parts.push("iwinfo " + ifname + " freqlist 2>&1 | sed " + shell_quote("s/^/f" + i + "|/") + " &");
        }
        let out = device.ssh(join_with(parts, " ") + " wait");
        let texts = [];
        let freqs = [];
        for i in 0..targets.len() { texts.push(""); freqs.push(""); }
        for line in lines(out.stdout) {
            let m = regex_groups(line, "^(f?)([0-9]+)\\|(.*)$");
            if m == () { continue; }
            let i = parse_int(m[1]);
            if m[0] == "f" { freqs[i] += m[2] + "\n"; } else { texts[i] += m[2] + "\n"; }
        }
        for i in 0..targets.len() {
            let t = targets[i];
            let o = sections[t.radio].options;
            rows.push(#{
                radio: t.radio, band: t.band,
                channel: o.channel ?? "auto", htmode: o.htmode ?? "",
                neighbors: parse_scan(texts[i]),
                "_allowed": parse_freqlist(freqs[i])
            });
        }
    }
    #{ radios: rows, "_own": own }
}

// O que "Roaming rápido e direcionamento" vai mudar, sem mudar nada.
fn preview_roaming(device, params) {
    let names = installed_names(device);
    let wpad = wpad_of(names);
    let changes = [];
    if !wpad_is_full(wpad) {
        if wpad != "nenhum" {
            changes.push(#{ change: "remover", "package": wpad, detail: "versão básica, sem roaming" });
        }
        changes.push(#{ change: "instalar", "package": "wpad-mbedtls", detail: "roaming 802.11r/k/v e mesh" });
    }
    if params.usteer && !names.contains("usteer") {
        changes.push(#{ change: "instalar", "package": "usteer", detail: "leva cada aparelho ao roteador mais perto" });
    }
    #{ summary: summary_text(changes), changes: changes }
}

fn prepare_roaming(device, params) {
    let log = [];
    let wpad = installed_wpad(device);
    if wpad_is_full(wpad) {
        log.push("O " + wpad + " já suporta roaming 802.11r/k/v e mesh.");
    } else {
        if wpad != "nenhum" {
            log.push(device.use_plugin("openwrt-packages", "remove_package", #{ name: wpad }));
        }
        try {
            log.push(device.use_plugin("openwrt-packages", "install_package", #{ name: "wpad-mbedtls" }));
        } catch (err) {
            if wpad != "nenhum" {
                device.use_plugin("openwrt-packages", "install_package", #{ name: wpad });
            }
            throw "Não foi possível instalar o wpad completo; o " + wpad + " foi reinstalado.\n" + err;
        }
    }
    if params.usteer {
        log.push(device.use_plugin("openwrt-packages", "install_package", #{ name: "usteer" }));
        device.run("/etc/init.d/usteer enable && /etc/init.d/usteer restart");
        log.push("usteer habilitado e iniciado.");
    }
    device.ssh("wifi reload");
    join_with(log, "\n")
}

