// Largura do canal em MHz pelo modo (`VHT80` → 80); sem número, 20.
fn width_of(htmode) {
    let digits = regex_capture(htmode, "(\\d+)$");
    if digits == () { 20 } else { parse_int(digits) }
}

// Dois canais se sobrepõem? Em 2,4 GHz os canais têm 22 MHz (1, 6 e 11 não
// se tocam); em 5 GHz cada número são 5 MHz, então a largura decide.
fn overlaps(band, a, b, width) {
    let gap = a - b;
    if gap < 0 { gap = -gap; }
    if band == "2g" {
        if width >= 40 { gap < 9 } else { gap < 5 }
    } else {
        gap * 5 < width
    }
}

// As redes vizinhas que um canal pegaria (as da própria frota não contam).
fn noise_on(band, ch, width, neighbors, own) {
    let count = 0;
    let strongest = -100;
    let cost = 0;
    for n in neighbors {
        if own.contains(n.ssid) || !overlaps(band, ch, n.channel, width) { continue; }
        count += 1;
        if n.signal > strongest { strongest = n.signal; }
        let weight = n.signal + 100;
        if weight > 0 { cost += weight; }
    }
    #{ count: count, strongest: strongest, cost: cost }
}

fn fleet_on(band, ch, width, taken) {
    let count = 0;
    for t in taken { if overlaps(band, ch, t, width) { count += 1; } }
    count
}

fn noise_text(noise, fleet) {
    let parts = [];
    if noise.count > 0 {
        parts.push(noise.count.to_string() + " rede(s) vizinha(s), a mais forte com " + noise.strongest.to_string() + " dBm");
    }
    if fleet > 0 { parts.push(fleet.to_string() + " roteador(es) da frota"); }
    if parts.len() == 0 { "nenhuma — canal livre" } else { join_with(parts, " e ") }
}

// Plano de canais: para cada rádio, o canal com menos interferência entre os
// que ele pode usar no país configurado (sem radar/DFS), sem repetir o de
// outro roteador da frota. O canal atual fica quando já é o mais limpo. Não
// muda nada: devolve em `next` a ação "Rádios e canais" com o canal de cada
// roteador, para o operador aceitar.
fn plan_channels(results, settings) {
    let own = [];
    for r in results {
        if r.status == "succeeded" && r.output != () {
            for ssid in r.output["_own"] ?? [] { if !own.contains(ssid) { own.push(ssid); } }
        }
    }
    let base = #{ "2g": [1, 6, 11], "5g": [36, 40, 44, 48, 149, 153, 157, 161, 165] };
    let taken = #{ "2g": [], "5g": [] };
    let assignments = [];
    let devices = #{};
    let moves = 0;
    for r in results {
        if r.status != "succeeded" || r.output == () { continue; }
        for radio in r.output.radios {
            let band = radio.band;
            if !base.contains(band) { continue; }
            let width = width_of(radio.htmode ?? "");
            let allowed = radio["_allowed"] ?? [];
            let candidates = [];
            for ch in base[band] {
                if allowed.len() == 0 || allowed.contains(ch) { candidates.push(ch); }
            }
            if candidates.len() == 0 { candidates = allowed; }
            if candidates.len() == 0 { continue; }

            let best = 0;
            let best_cost = 1000000;
            for ch in candidates {
                let cost = noise_on(band, ch, width, radio.neighbors, own).cost + fleet_on(band, ch, width, taken[band]) * 60;
                if cost < best_cost { best_cost = cost; best = ch; }
            }
            let current = if radio.channel == "auto" { 0 } else { parse_int(radio.channel) };
            let current_known = current > 0;
            let current_noise = noise_on(band, current, width, radio.neighbors, own);
            let current_fleet = fleet_on(band, current, width, taken[band]);
            let current_allowed = current_known && (allowed.len() == 0 || allowed.contains(current));
            let keep = current_allowed && current_noise.cost + current_fleet * 60 <= best_cost;
            let choice = if keep { current } else { best };
            taken[band].push(choice);

            assignments.push(#{
                device: r.deviceName, band: band_label(band),
                current: if current_known { radio.channel } else { "automático" },
                current_noise: if current_known { noise_text(current_noise, current_fleet) } else { "—" },
                channel: choice.to_string(),
                suggested_noise: noise_text(noise_on(band, choice, width, radio.neighbors, own), fleet_on(band, choice, width, taken[band]) - 1),
                decision: if keep { "manter" } else { "alterar" }
            });
            if !keep {
                moves += 1;
                let key = r.deviceId.to_string();
                if !devices.contains(key) { devices[key] = #{}; }
                devices[key]["radio_" + band + "_channel"] = choice.to_string();
            }
        }
    }
    let out = #{
        summary: if moves == 0 {
            "Todos os rádios já estão no canal mais limpo que podem usar. Nada a mudar."
        } else {
            moves.to_string() + " rádio(s) mudam de canal; os outros ficam como estão. Aceite para aplicar."
        },
        how: "Para cada rádio, o plano compara só os canais que ele pode usar no país configurado (sem os canais de radar/DFS) e escolhe o que tem menos redes vizinhas, pesando pela força do sinal, sem repetir o canal de outro roteador da frota. Se o canal atual já é o mais limpo, ele fica.",
        assignments: assignments
    };
    if moves > 0 {
        out.next = #{ action: "radios", title: "Aplicar o plano de canais", devices: devices };
    }
    out
}
